"""将正式映射生成可离线打开的资产总览；全部素材使用相对路径。"""
import json
from pathlib import Path

PROJECT = Path(__file__).resolve().parents[1]
ASSETS = PROJECT / 'Game/Assets/Cards/正式卡牌'
manifest = json.loads((ASSETS / '卡牌资产映射.json').read_text(encoding='utf-8'))
html = '''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>小泥团，出击！ · 卡牌资产总览</title>
<style>
*{box-sizing:border-box}body{margin:0;background:#141e26;color:#f5ead5;font:16px "Microsoft YaHei",sans-serif}header{padding:32px max(28px,calc((100vw - 1440px)/2));background:#202e37;border-bottom:1px solid #43505a}h1{margin:0 0 12px;font-size:30px}p{color:#b6c0c5;line-height:1.7}nav{display:flex;flex-wrap:wrap;gap:10px;margin-top:24px}button,input,select{border:1px solid #637079;background:#17232b;color:#f5ead5;border-radius:8px;padding:10px 16px;font:inherit}button{cursor:pointer}button.active{background:#c29950;color:#1a2228}input{min-width:260px}main{max-width:1480px;padding:28px 20px 60px;margin:auto}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:24px}.entry{background:#202e37;border:1px solid #3c4a54;border-radius:14px;padding:14px}.face{position:relative;aspect-ratio:2/3;width:100%;container-type:inline-size;overflow:hidden}.face .shell{position:absolute;inset:0;width:100%;height:100%;z-index:2}.face .art{position:absolute;left:11.13%;top:22.14%;width:77.73%;height:29.56%;object-fit:cover;border-radius:7%;z-index:1}.cost,.title,.kind,.effect,.foot{position:absolute;z-index:3;display:flex;align-items:center;justify-content:center}.cost{left:11.7%;top:7.9%;width:16.2%;height:10.7%;font-size:12cqw;color:white;text-shadow:1px 1px 2px #16506a}.title{left:34%;top:8.8%;width:38.1%;height:8.1%;color:#412a20;font-weight:bold;font-size:8cqw;white-space:nowrap}.kind{left:14.6%;top:55.3%;width:70.7%;height:4.3%;font-size:4.8cqw;color:#866345}.effect{left:14.9%;top:60.5%;width:70.1%;height:22.7%;font-size:5.8cqw;color:#412a20;white-space:pre-line;justify-content:flex-start;line-height:1.45}.foot{left:17.6%;top:89.2%;width:64.8%;height:5.2%;font-size:5.2cqw;color:#ffedc8}.id{font-family:Consolas,monospace;color:#d9bd82;margin:12px 0 8px}.links{display:flex;gap:18px;margin:10px 0}a{color:#a4d5ec}.details{font-size:13px;color:#c7d1d6;overflow-wrap:anywhere}details{margin-top:10px}summary{cursor:pointer}pre{white-space:pre-wrap;font-family:inherit;font-size:14px;line-height:1.7}.counter{margin:0 0 20px;color:#c8d0d4}.tag{font-size:12px;background:#30483e;color:#addec0;padding:3px 7px;border-radius:4px}.empty{padding:60px;color:#a4b5c0}footer{max-width:1440px;margin:0 auto 40px;color:#9cabb4;font-size:13px}
</style>
<header><h1>小泥团，出击！ · 卡牌资产总览</h1><p>四套外壳 · 56 张独立插图 · 升级卡复用基础插图<br>在下方查找卡牌，打开原图、外壳或核对对应效果。</p>
<nav id="routes"><button class="active" data-route="all">全部</button><button data-route="neutral">通用</button><button data-route="fury">狂刃</button><button data-route="bastion">铁壁</button><button data-route="venom">蚀毒</button><input id="search" placeholder="搜索卡名、ID、效果" aria-label="搜索卡牌"><select id="version" aria-label="卡牌版本"><option value="base">基础版</option><option value="upgrade">升级版</option></select></nav></header>
<main><div class="counter" id="counter"></div><div class="grid" id="grid"></div></main><footer>制作日期：2026-11-13。文字为资产清单快照，游戏中的实时数值以独立 Card Resource 为准。全部路径均为相对路径，可随整个正式卡牌目录一同迁移。</footer>
<script>const data=__MANIFEST__;
const routes={neutral:'通用',fury:'狂刃',bastion:'铁壁',venom:'蚀毒'};let route='all';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function render(){const query=document.querySelector('#search').value.toLowerCase();const upgraded=document.querySelector('#version').value==='upgrade';const cards=Object.values(data.cards).filter(c=>(route==='all'||c.route===route)&&[c.name,c.id,c.description].join(' ').toLowerCase().includes(query));document.querySelector('#counter').textContent=`当前显示 ${cards.length} / ${Object.keys(data.cards).length} 张卡牌`;
document.querySelector('#grid').innerHTML=cards.map(c=>{const description=upgraded?c.upgraded_description:c.description;const size=description.length>95?3.8:description.length>60?4.6:5.8;return `<article class="entry"><div class="face"><img class="art" src="${encodeURI(c.illustration)}" alt="${esc(c.name)}插图" loading="lazy"><img class="shell" src="${encodeURI(c.shell)}" alt="${routes[c.route]}外壳" loading="lazy"><div class="cost">${esc(upgraded?c.upgraded_cost:c.cost)}</div><div class="title" style="${upgraded?'color:#9e3528;font-size:7.2cqw':''}">${esc(c.name)+(upgraded?'+':'')}</div><div class="kind">${esc(c.kind)} · ${routes[c.route]}</div><div class="effect" style="font-size:${size}cqw">${esc(description)}</div><div class="foot">${upgraded?'已升级':routes[c.route]+'卡牌'}</div></div><div class="id">${esc(c.id)} <span class="tag">${c.status==='ready'?'已接入':'待制作'}</span></div><div class="links"><a href="${encodeURI(c.illustration)}" target="_blank">打开插图</a><a href="${encodeURI(c.shell)}" target="_blank">打开外壳</a></div><div class="details">${esc(c.illustration)}</div><details><summary>完整效果与资产信息</summary><pre>${esc(description)}</pre><div class="details">容量: ${esc((c.bytes/1000).toFixed(1))} KB / 上限 500 KB<br>格式: WebP · 质量 ${esc(c.compression?.quality||95)}<br>SHA-256: ${esc(c.sha256||'待核验')}<br>尺寸: ${esc((c.size||[]).join(' × '))}<br>升级插图: 复用基础图</div></details></article>`}).join('')||'<div class="empty">没有匹配的卡牌</div>';}
document.querySelector('#routes').addEventListener('click',e=>{if(!e.target.dataset.route)return;route=e.target.dataset.route;document.querySelectorAll('#routes button').forEach(b=>b.classList.toggle('active',b===e.target));render()});document.querySelector('#search').addEventListener('input',render);document.querySelector('#version').addEventListener('change',render);render();</script></html>'''
(ASSETS / '卡牌资产总览.html').write_text(html.replace('__MANIFEST__', json.dumps(manifest, ensure_ascii=False).replace('</','<\\/')), encoding='utf-8')
print('Generated local card asset catalog')
